import{_ as e,o as d,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"The service surface map","description":"","frontmatter":{},"headers":[],"relativePath":"l1/surface-map.md","filePath":"l1/surface-map.md"}'),r={name:"l1/surface-map.md"};function o(i,t,c,n,l,p){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="the-service-surface-map" tabindex="-1">The service surface map <a class="header-anchor" href="#the-service-surface-map" aria-label="Permalink to &quot;The service surface map&quot;">​</a></h1><p>Every L1SVC category, what it fronts, and the apps that wrap it. The numbering contract is <code>ocos/interface/l1svc_ops.h</code> (mirrored from <code>ocos/services/sysapi/interface/svc_sysapi_l1svc.h</code>; renumber upstream only by appending, then regenerate).</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cat</th><th>Name</th><th>Fronts</th><th>Mega-app home</th></tr></thead><tbody><tr><td>1</td><td>time</td><td>RTC / HPET / PM timer / TSC status</td><td>hwinfo</td></tr><tr><td>2</td><td>block</td><td>disks: status, partition, mkfs, fsck, A/B tools, tests</td><td>disk-tool</td></tr><tr><td>3</td><td>nic</td><td>NIC families + wireless (wifi/bt)</td><td>net-tool</td></tr><tr><td>4</td><td>snd</td><td>audio devices, volume, play, per-driver tests</td><td>sound-tool</td></tr><tr><td>5</td><td>power</td><td>shutdown/reboot/halt/sleep + path tests</td><td>power</td></tr><tr><td>6</td><td>ota (selfhost)</td><td>update chain, checkupdate, config store, A/B</td><td>update</td></tr><tr><td>7</td><td>fs</td><td>mount/umount/fatmount/fatstat/tree</td><td>disk-tool, files</td></tr><tr><td>8</td><td>net</td><td>ip/dhcp/dns/arp/route/firewall/ssh/sshd</td><td>net-tool</td></tr><tr><td>9</td><td>health</td><td>snapshot / export / watch</td><td>sysdiag</td></tr><tr><td>10</td><td>klog</td><td>dmesg / logcat / logctl</td><td>sysdiag</td></tr><tr><td>11</td><td>watchdog</td><td>the watchdog command family</td><td>sysdiag</td></tr><tr><td>12</td><td>crypto</td><td>cryptotest / dhtest</td><td>(classic only)</td></tr><tr><td>13</td><td>l1</td><td>the registry listing itself (help -a/-w), l1test, ldd</td><td>-</td></tr><tr><td>14</td><td>display</td><td>uname/stats/lang/font/encoding/IME ops</td><td>hwinfo</td></tr><tr><td>15</td><td>input</td><td>touchpad / touchtest</td><td>hwinfo</td></tr><tr><td>16</td><td>camera</td><td>uvc/scsi/gameport/parallel/ir + tests</td><td>hwinfo</td></tr><tr><td>17</td><td>usb</td><td>usb status/dev + the usb test family</td><td>hwinfo</td></tr><tr><td>18</td><td>ocire</td><td>the boot-volume log ring (guard-only ops)</td><td>-</td></tr><tr><td>19</td><td>diag</td><td>memory/scheduler/vm tests, PCI/ACPI/I2C/SMBus, crash</td><td>sysdiag</td></tr><tr><td>20</td><td>tui</td><td>the desktop + TUI command family</td><td>(tui apps)</td></tr></tbody></table><h2 id="beyond-l1svc-the-direct-syscalls" tabindex="-1">Beyond L1SVC: the direct syscalls <a class="header-anchor" href="#beyond-l1svc-the-direct-syscalls" aria-label="Permalink to &quot;Beyond L1SVC: the direct syscalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syscall</th><th>Used by</th></tr></thead><tbody><tr><td><code>SYS_OPEN/READ/WRITE/CLOSE/STAT/READDIR</code></td><td>the file tools (cat, cp, ls, ...)</td></tr><tr><td><code>SYS_FORK/EXECVE/WAIT4</code></td><td>ush, run, files - the program-launcher pattern</td></tr><tr><td><code>SYS_PIPE/DUP/DUP2</code></td><td>ush pipes and redirection</td></tr><tr><td><code>SYS_READLINE</code> (73)</td><td>wizard line input (echo + backspace, blocking)</td></tr><tr><td><code>SYS_GETCH</code> (74)</td><td>non-blocking single keys (menus, the editor)</td></tr><tr><td><code>SYS_NETCMD</code> (101)</td><td>ping / wget / ifconfig / netstat bridge</td></tr><tr><td><code>SYS_PS</code> (102)</td><td>ps / top process tables</td></tr></tbody></table><p>The full x86_64 syscall table is registered in <code>ocos/services/sysapi/src/svc_sysapi_syscall.c</code>.</p><h2 id="the-output-contract" tabindex="-1">The output contract <a class="header-anchor" href="#the-output-contract" aria-label="Permalink to &quot;The output contract&quot;">​</a></h2><p>Service ops return <strong>English ASCII text</strong> through the caller&#39;s buffer - these lines are the script-facing contract and the wizard probes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;IP: 10.0.2.15&quot;            (net ip)</span></span>
<span class="line"><span>&quot;DHCP success: IP=...&quot;     (net dhcp)</span></span>
<span class="line"><span>&quot;A/B disk: present&quot;        (ota update status)</span></span>
<span class="line"><span>&quot;New version available.&quot;   (ota checkupdate)</span></span>
<span class="line"><span>&quot;Current version is up to date.&quot;</span></span>
<span class="line"><span>&quot;reboot required&quot;          (ota update, after install)</span></span></code></pre></div><p>Renaming any of them is a breaking change: the wizards (<code>wizard_lib.h</code> <code>wiz_find</code>), the E2E suites and the user docs all read them.</p><h2 id="help-a-help-w" tabindex="-1">help -a / help -w <a class="header-anchor" href="#help-a-help-w" aria-label="Permalink to &quot;help -a / help -w&quot;">​</a></h2><p>The registry listing (L1SVC cat &quot;l1&quot; op 1) renders name + wp tag + bilingual hint per program. <code>help -w</code> groups by tag; the <code>mega</code> group (the 8 merged apps) leads the view, followed by the 18 historical service groups.</p>`,13)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
